<?php
require_once __DIR__.'/../includes/auth.php'; require_login();
$id=filter_var($_GET['id'] ?? null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]); if (!$id) { http_response_code(400); exit('Invalid flight ID.'); }
$s=$pdo->prepare('SELECT f.*,a.registration FROM flight_logs f JOIN aircraft a ON a.id=f.aircraft_id WHERE f.id=?'); $s->execute([$id]); $flight=$s->fetch(); if (!$flight) { http_response_code(404); exit('Flight not found.'); }
$s=$pdo->prepare('SELECT c.*,u.name AS corrected_by_name FROM flight_corrections c LEFT JOIN users u ON u.id=c.corrected_by WHERE c.flight_id=? ORDER BY c.id DESC'); $s->execute([$id]); $corrections=$s->fetchAll();
$page_title='Flight correction history'; include __DIR__.'/../includes/header.php'; ?>
<h1>Flight #<?= (int)$id ?> — <?= esc($flight['registration']) ?></h1><p>Current entry: <?= esc($flight['flight_date']) ?> · <?= esc($flight['pilot_name']) ?> · Tach <?= esc($flight['tach_start']) ?> → <?= esc($flight['tach_end']) ?> · Hobbs <?= esc($flight['hobbs_start']) ?> → <?= esc($flight['hobbs_end']) ?> · Total time <?= esc($flight['total_time_start']) ?> → <?= esc($flight['total_time_end']) ?> · <?= (int)$flight['landings'] ?> landing(s) · <?= (int)$flight['cycles'] ?> cycle(s)</p>
<?php if (in_array(user()['role'],['ADMIN','MANAGER'])): ?><div class="actions"><a class="btn" href="<?= esc(url('flights/correct.php?id='.$id)) ?>">Correct latest flight</a></div><?php endif; ?>
<h2>Correction history</h2><?php foreach ($corrections as $c): $before=json_decode($c['before_json'],true); $after=json_decode($c['after_json'],true); ?><div class="card"><p><strong><?= esc($c['created_at']) ?> · <?= esc($c['corrected_by_name'] ?? 'Former user') ?></strong></p><p><strong>Reason:</strong> <?= nl2br(esc($c['reason'])) ?></p><div class="table-wrap"><table><tr><th>Field</th><th>Before</th><th>After</th></tr><?php foreach ($after as $key=>$value): if ((string)($before[$key] ?? '')===(string)($value ?? '')) continue; ?><tr><td><?= esc(str_replace('_',' ',$key)) ?></td><td><?= nl2br(esc($before[$key] ?? '')) ?></td><td><?= nl2br(esc($value)) ?></td></tr><?php endforeach; ?></table></div></div><?php endforeach; ?><?php if (!$corrections): ?><p>No corrections recorded.</p><?php endif; ?>
<p><a href="<?= esc(url('flights/?aircraft_id='.(int)$flight['aircraft_id'])) ?>">Back to flights</a></p><?php include __DIR__.'/../includes/footer.php'; ?>
